#!/usr/bin/env python3
"""Generate the CSS for the home page's animated product demos.

The cpp-linter, AccessLens and keelinfra demos
(layouts/partials/home/demo-{cpp-linter,accesslens,keelinfra}.html) are pure CSS. Each element that appears, swaps or
moves has its own keyframes, and a scene change touches dozens of them, so the
timelines live here as plain data -- "visible from 26% to 49% of the loop",
"cursor at (474, 238) at 42%" -- and this script writes the CSS.

The output replaces the block between the BEGIN/END markers in
assets/css/custom.css. Edit this script, not that block. The Keelhaven demo is
not generated: it is ported by hand from keelhaven.app and lives outside the
markers.

    python3 .github/scripts/gen_demo_css.py           # rewrite the block
    python3 .github/scripts/gen_demo_css.py --check   # exit 1 if it is stale

Timings are percentages of each loop (cpp-linter 20s, AccessLens 16s,
keelinfra 18s). The
header comment of each partial says what happens when. Cursor coordinates are
pixels inside the fixed-size demo window, measured to the pointer's tip.
"""

import argparse
import os
import sys

REPO_ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
CSS_PATH = os.path.join(REPO_ROOT, "assets", "css", "custom.css")
BEGIN = "/* BEGIN generated by .github/scripts/gen_demo_css.py -- edit the script, not this block */\n"
END = "/* END generated by .github/scripts/gen_demo_css.py */\n"

# Default fade, in percent of the loop, when an element appears or disappears.
F = 0.8


def vis(name, intervals, f=F):
    """Opacity keyframes: visible during each (start, end) window, else hidden.

    Windows are percentages, in order and non-overlapping. A window starting at
    0 or ending at 100 is visible across the loop boundary.
    """
    pts = {}
    if intervals[0][0] > 0:
        pts[0] = 0
    for a, b in intervals:
        if a > 0:
            pts[round(a - f, 2)] = 0
            pts[a] = 1
        else:
            pts[0] = 1
        pts[b] = 1
        if b < 100:
            pts[round(b + f, 2)] = 0
        else:
            pts[100] = 1
    if intervals[-1][1] < 100:
        pts[100] = 0
    body = " ".join(f"{k:g}% {{ opacity: {pts[k]}; }}" for k in sorted(pts))
    return f"@keyframes {name} {{ {body} }}"


def props(name, frames):
    """Keyframes from (selector, declarations) pairs, written as given."""
    body = " ".join(f"{k} {{ {v} }}" for k, v in frames)
    return f"@keyframes {name} {{ {body} }}"


