# Keyframes: scene layers, tab underlines, then content appearing in a scene.
cl_k = [
 vis("cl-demo-s-conv", [(2, 24), (76, 98)]),
 vis("cl-demo-s-files", [(26, 49)]),
 vis("cl-demo-s-checks", [(51, 74)]),
 vis("cl-demo-u-conv", [(0, 25), (75, 100)], 0.01),
 vis("cl-demo-u-files", [(25, 50)], 0.01),
 vis("cl-demo-u-checks", [(50, 75)], 0.01),
 vis("cl-demo-in-comment", [(5, 100)]),
 vis("cl-demo-in-fail", [(10, 24)]),
 vis("cl-demo-in-push", [(80, 100)]),
 vis("cl-demo-in-review", [(30, 100)]),
 vis("cl-demo-in-summary", [(55, 100)]),
]
# The chip row: the input behind the current scene is highlighted.
on = "background: rgb(var(--color-primary-400)); border-color: rgb(var(--color-primary-400)); color: rgb(var(--color-neutral-900));"
off = "background: transparent; border-color: rgb(var(--color-neutral-600)); color: rgb(var(--color-neutral-400));"
for i, (a, b) in enumerate([(0, 25), (25, 50), (50, 75), (75, 100)], 1):
    fr = []
    if a > 0: fr += [("0%", off), (f"{a-0.5:g}%", off)]
    fr += [(f"{a}%" if a else "0%", on), (f"{b-0.5:g}%" if b < 100 else "100%", on)]
    if b < 100: fr += [(f"{b}%", off), ("100%", off)]
    cl_k.append(props(f"cl-demo-v{i}", fr))

